public void handleField(str _value, FormGroupControl _fgc)
{

    TFMBackendIDInstance    backendInstance = TFMBackendIDInstance::Construct(_value);
    FormStringControl       fsc = _fgc.addControl(FormControlType::String,TFMConstants::BackendId()+'_'+backendInstance.parmFieldName());
    SysDictField            sdf = new SysDictField(tableName2Id(backendInstance.parmTableName()),fieldName2Id(tableName2Id(backendInstance.parmTableName()), backendInstance.parmFieldName()));

    if (sdf.baseType() == Types::String)
    {
        fsc.extendedDataType(sdf.typeId());
    }
    fsc.text(backendInstance.parmFieldValue());

}
